populateDialogueExamples.text:
async function populateDialogueExamples(prompts, chatCompletion, messageExamples, runtime = null) {
    const assemblyRuntime = getPromptAssemblyRuntime(runtime);
    const settings = assemblyRuntime.settings;
    const assemblyTokenHandler = assemblyRuntime.tokenHandler;

    if (!prompts.has('dialogueExamples')) {
        return;
    }

    chatCompletion.add(new MessageCollection('dialogueExamples'), prompts.index('dialogueExamples'));
    if (Array.isArray(messageExamples) && messageExamples.length) {
            const newExampleChat = await Message.createAsync('system', substitutePromptParams(settings.new_example_chat_prompt, {}, assemblyRuntime), 'newChat', assemblyTokenHandler);
        for (const dialogue of [...messageExamples]) {
            const dialogueIndex = messageExamples.indexOf(dialogue);
            const chatMessages = [];

            for (let promptIndex = 0; promptIndex < dialogue.length; promptIndex++) {
                const prompt = dialogue[promptIndex];
                const role = 'system';
                const content = prompt.content || '';
                const identifier = `dialogueExamples ${dialogueIndex}-${promptIndex}`;

                const chatMessage = await Message.createAsync(role, content, identifier, assemblyTokenHandler);
                await chatMessage.setName(prompt.name, assemblyTokenHandler);
                chatMessages.push(chatMessage);
            }

            if (!chatCompletion.canAffordAll([newExampleChat, ...chatMessages])) {
                break;
            }

            chatCompletion.insert(newExampleChat, 'dialogueExamples');
            for (const chatMessage of chatMessages) {
                chatCompletion.insert(chatMessage, 'dialogueExamples');
            }
        }
    }
}

populationInjectionPrompts.text:
async function populationInjectionPrompts(prompts, messages, extensionPrompts = null, runtime = null) {
    const assemblyRuntime = getPromptAssemblyRuntime(runtime);
    let totalInsertedMessages = 0;

    const roleTypes = {
        'system': extension_prompt_roles.SYSTEM,
        'user': extension_prompt_roles.USER,
        'assistant': extension_prompt_roles.ASSISTANT,
    };

    const maxDepth = getExtensionPromptMaxDepth();
    for (let i = 0; i <= maxDepth; i++) {
        // Get prompts for current depth
        const depthPrompts = prompts.filter(prompt => prompt.injection_depth === i && prompt.content);

        const roleMessages = [];
        const separator = '\n';
        const wrap = false;

        // Group prompts by priority
        const extensionPromptsOrder = '100';
        const orderGroups = {
            [extensionPromptsOrder]: [],
        };
        for (const prompt of depthPrompts) {
            const order = prompt.injection_order ?? 100;
            if (!orderGroups[order]) {
                orderGroups[order] = [];
            }
            orderGroups[order].push(prompt);
        }

        // Process each order group in order (b - a = low to high ; a - b = high to low)
        const orders = Object.keys(orderGroups).sort((a, b) => +b - +a);
        for (const order of orders) {
            const orderPrompts = orderGroups[order];

            // Order of priority for roles (most important go lower)
            const roles = ['system', 'user', 'assistant'];
            for (const role of roles) {
                const rolePrompts = orderPrompts
                    .filter(prompt => prompt.role === role)
                    .map(x => x.content)
                    .join(separator);

                // Get extension prompt
                const extensionPrompt = order === extensionPromptsOrder
                    ? await getPromptAssemblyExtensionPrompt(extensionPrompts, extension_prompt_types.IN_CHAT, i, separator, roleTypes[role], wrap, assemblyRuntime)
                    : '';
                const jointPrompt = [rolePrompts, extensionPrompt].filter(x => x).map(x => x.trim()).join(separator);

                if (jointPrompt && jointPrompt.length) {
                    roleMessages.push({ 'role': role, 'content': jointPrompt, injected: true });
                }
            }
        }

        if (roleMessages.length) {
            const injectIdx = i + totalInsertedMessages;
            messages.splice(injectIdx, 0, ...roleMessages);
            totalInsertedMessages += roleMessages.length;
        }
    }

    messages = messages.reverse();
    return messages;
}

getPromptAssemblyExtensionPrompt.text:
async function getPromptAssemblyExtensionPrompt(extensionPrompts, position, depth, separator, role, wrap, runtime = null) {
    const source = normalizePromptAssemblyExtensionPrompts(extensionPrompts);
    if (!source) {
        return '';
    }

    const promptPromises = Object.keys(source)
        .sort()
        .map(key => source[key])
        .filter(prompt => prompt.position == position && prompt.value)
        .filter(prompt => depth === undefined || prompt.depth === undefined || prompt.depth === depth)
        .filter(prompt => role === undefined || prompt.role === undefined || prompt.role === role)
        .map(async prompt => {
            if (typeof prompt.filter === 'function' && !await prompt.filter()) {
                return null;
            }
            return prompt;
        });
    const prompts = (await Promise.all(promptPromises)).filter(Boolean);

    let values = prompts.map(prompt => String(prompt.value).trim()).join(separator);
    if (wrap && values.length && !values.startsWith(separator)) {
        values = separator + values;
    }
    if (wrap && values.length && !values.endsWith(separator)) {
        values = values + separator;
    }
    if (values.length) {
        values = substitutePromptParams(values, {}, runtime);
    }
    return values;
}

normalizePromptAssemblyExtensionPrompts.text:
function normalizePromptAssemblyExtensionPrompts(value) {
    if (value == null) {
        return null;
    }
    if (typeof value !== 'object' || Array.isArray(value)) {
        throw new Error('prompt_assembly.extension_prompts_invalid: extensionPrompts must be an object');
    }
    return value;
}

applyAttachedPromptsToMessages.text:
export function applyAttachedPromptsToMessages(attachedPrompts, messages, { warn = console.warn } = {}) {
    if (!Array.isArray(attachedPrompts) || !attachedPrompts.length || !Array.isArray(messages) || !messages.length) {
        return 0;
    }

    let applied = 0;

    for (const attachPrompt of attachedPrompts) {
        const attachContent = String(attachPrompt?.content ?? '').trim();
        const attachRole = String(attachPrompt?.attach_role ?? '').trim();
        const attachSide = String(attachPrompt?.attach_side ?? 'end').trim();
        const rawIndex = attachPrompt?.attach_index ?? 1;

        if (!attachContent) {
            continue;
        }

        if (!ATTACH_ROLES.has(attachRole)) {
            warn?.(`[PromptManager] Attach prompt "${describePrompt(attachPrompt)}" has an invalid target role: ${attachRole || '(empty)'}.`);
            continue;
        }

        const requestedIndex = normalizeAttachIndex(rawIndex, attachPrompt, warn);
        if (requestedIndex === null) {
            continue;
        }

        const chronologicalRoleMatches = messages
            .filter(message => message && !message.injected && message.role === attachRole)
            .slice()
            .reverse();

        if (!chronologicalRoleMatches.length) {
            warn?.(`[PromptManager] Attach prompt "${describePrompt(attachPrompt)}" found no existing ${attachRole} messages.`);
            continue;
        }

        const targetIndex = clampAttachIndex(requestedIndex, chronologicalRoleMatches.length);
        const targetMessage = chronologicalRoleMatches[targetIndex];
        const currentContent = String(targetMessage.content ?? '');
        const side = ATTACH_SIDES.has(attachSide) ? attachSide : 'end';

        if (!ATTACH_SIDES.has(attachSide)) {
            warn?.(`[PromptManager] Attach prompt "${describePrompt(attachPrompt)}" has an invalid attach side: ${attachSide || '(empty)'}. Using end.`);
        }

        targetMessage.content = side === 'start'
            ? [attachContent, currentContent].filter(Boolean).join('\n\n')
            : [currentContent, attachContent].filter(Boolean).join('\n\n');
        applied += 1;
    }

    return applied;
}

normalizeAttachIndex.text:
function normalizeAttachIndex(rawIndex, prompt, warn) {
    const index = Number(rawIndex);
    if (!Number.isFinite(index) || !Number.isInteger(index)) {
        warn?.(`[PromptManager] Attach prompt "${describePrompt(prompt)}" has an invalid message index: ${String(rawIndex)}.`);
        return null;
    }

    return index === 0 ? 1 : index;
}

clampAttachIndex.text:
function clampAttachIndex(index, length) {
    if (index > 0) {
        return Math.min(index - 1, length - 1);
    }

    return Math.max(length + index, 0);
}

preparePrompt.text:
preparePrompt(prompt, original = null) {
    const groupMembers = this.getActiveGroupCharacters();
    const preparedPrompt = new Prompt(prompt);
    const substitute = typeof this.substituteParams === 'function' ? this.substituteParams : substituteParams;

    if (typeof original === 'string') {
        if (0 < groupMembers.length) preparedPrompt.content = substitute(prompt.content ?? '', { original, groupOverride: groupMembers.join(', ') });
        else preparedPrompt.content = substitute(prompt.content, { original });
    } else {
        if (0 < groupMembers.length) preparedPrompt.content = substitute(prompt.content ?? '', { groupOverride: groupMembers.join(', ') });
        else preparedPrompt.content = substitute(prompt.content);
    }

    return preparedPrompt;
}

setChatCompletion.text:
setChatCompletion(chatCompletion) {
    this.#dryRunPending = false;
    const messages = chatCompletion.getMessages();

    this.setMessages(messages);
    this.populateTokenCounts(messages);
    this.overriddenPrompts = chatCompletion.getOverriddenPrompts();
}

getPromptCollection.text:
getPromptCollection(generationType) {
    generationType = String(generationType || 'normal').toLowerCase().trim();
    const promptCollection = new PromptCollection();
    const promptOrder = this.getPromptOrderForCharacter(this.activeCharacter);

    promptOrder.forEach(entry => {
        const prompt = this.getPromptById(entry.identifier);
        const allowedTrigger = entry.enabled && this.shouldTrigger(prompt, generationType);

        if (!prompt) {
            return;
        }

        if (allowedTrigger) {
            promptCollection.add(this.preparePrompt(prompt));
        } else if (entry.identifier === 'main') {
            // Some extensions require main prompt to be present for relative inserts.
            // So we make a GMO-free vegan replacement.
            const replacementPrompt = structuredClone(prompt);
            replacementPrompt.content = '';
            promptCollection.add(this.preparePrompt(replacementPrompt));
        }
    });

    return promptCollection;
}

replaceFrozenOutletMacros.text:
function replaceFrozenOutletMacros(content, extensionPrompts) {
    if (!extensionPrompts || typeof content !== 'string' || !content.includes('{{outlet::')) {
        return content;
    }

    return content.replace(/{{outlet::(.+?)}}/gi, (_, key) => {
        return getOutletPromptFromExtensionPrompts(extensionPrompts, String(key ?? '').trim());
    });
}

getOutletPromptFromExtensionPrompts.text:
function getOutletPromptFromExtensionPrompts(extensionPrompts, key) {
    if (!key) {
        return '';
    }

    const outletPrompt = extensionPrompts[inject_ids.CUSTOM_WI_OUTLET(key)];

    return stringOrEmpty(outletPrompt?.value);
}

stringOrEmpty.text:
function stringOrEmpty(value) {
    return value == null ? '' : String(value);
}

evaluateMacros.text:
export function evaluateMacros(content, env, postProcessFn) {
    if (!content) {
        return '';
    }

    postProcessFn = typeof postProcessFn === 'function' ? postProcessFn : (x => x);
    const rawContent = content;

    /**
     * Built-ins running before the env variables
     * @type {Macro[]}
     * */
    const preEnvMacros = [
        // Legacy non-curly macros
        { regex: /<USER>/gi, replace: () => typeof env.user === 'function' ? env.user() : env.user },
        { regex: /<BOT>/gi, replace: () => typeof env.char === 'function' ? env.char() : env.char },
        { regex: /<CHAR>/gi, replace: () => typeof env.char === 'function' ? env.char() : env.char },
        { regex: /<CHARIFNOTGROUP>/gi, replace: () => typeof env.group === 'function' ? env.group() : env.group },
        { regex: /<GROUP>/gi, replace: () => typeof env.group === 'function' ? env.group() : env.group },
        getDiceRollMacro(),
        ...getInstructMacros(env),
        ...getVariableMacros(),
        { regex: /{{newline}}/gi, replace: () => '\n' },
        { regex: /(?:\r?\n)*{{trim}}(?:\r?\n)*/gi, replace: () => '' },
        { regex: /{{noop}}/gi, replace: () => '' },
        { regex: /{{input}}/gi, replace: () => String($('#send_textarea').val()) },
    ];

    /**
     * Built-ins running after the env variables
     * @type {Macro[]}
    */
    const postEnvMacros = [
        { regex: /{{maxPrompt}}/gi, replace: () => String(getMaxPromptTokens()) },
        { regex: /{{maxPromptTokens}}/gi, replace: () => String(getMaxPromptTokens()) },
        { regex: /{{maxContext}}/gi, replace: () => String(getMaxContextTokens()) },
        { regex: /{{maxContextTokens}}/gi, replace: () => String(getMaxContextTokens()) },
        { regex: /{{maxResponse}}/gi, replace: () => String(getMaxResponseTokens()) },
        { regex: /{{maxResponseTokens}}/gi, replace: () => String(getMaxResponseTokens()) },
        { regex: /{{lastMessage}}/gi, replace: () => getLastMessage() },
        { regex: /{{lastMessageId}}/gi, replace: () => String(getLastMessageId() ?? '') },
        { regex: /{{lastUserMessage}}/gi, replace: () => getLastUserMessage() },
        { regex: /{{lastCharMessage}}/gi, replace: () => getLastCharMessage() },
        { regex: /{{firstIncludedMessageId}}/gi, replace: () => String(getFirstIncludedMessageId() ?? '') },
        { regex: /{{firstDisplayedMessageId}}/gi, replace: () => String(getFirstDisplayedMessageId() ?? '') },
        { regex: /{{lastSwipeId}}/gi, replace: () => String(getLastSwipeId() ?? '') },
        { regex: /{{currentSwipeId}}/gi, replace: () => String(getCurrentSwipeId() ?? '') },
        { regex: /{{allChatRange}}/gi, replace: () => chat.length === 0 ? '' : `0-${chat.length - 1}` },
        { regex: /{{reverse:(.+?)}}/gi, replace: (_, str) => Array.from(str).reverse().join('') },
        { regex: /\{\{\/\/([\s\S]*?)\}\}/gm, replace: () => '' },
        { regex: /{{time}}/gi, replace: () => moment().format('LT') },
        { regex: /{{date}}/gi, replace: () => moment().format('LL') },
        { regex: /{{weekday}}/gi, replace: () => moment().format('dddd') },
        { regex: /{{isotime}}/gi, replace: () => moment().format('HH:mm') },
        { regex: /{{isodate}}/gi, replace: () => moment().format('YYYY-MM-DD') },
        { regex: /{{datetimeformat +([^}]*)}}/gi, replace: (_, format) => moment().format(format) },
        { regex: /{{idle_duration}}/gi, replace: () => getTimeSinceLastMessage() },
        { regex: /{{time_UTC([-+]\d+)}}/gi, replace: (_, offset) => moment().utc().utcOffset(parseInt(offset, 10)).format('LT') },
        { regex: /{{outlet::(.+?)}}/gi, replace: (_, key) => getOutletPrompt(key.trim()) || '' },
        getTimeDiffMacro(),
        getBannedWordsMacro(),
        getRandomReplaceMacro(),
        getPickReplaceMacro(rawContent),
    ];

    // Add all registered macros to the env object
    MacrosParser.populateEnv(env);
    const nonce = uuidv4();
    const envMacros = [];

    // Substitute passed-in variables
    for (const varName in env) {
        if (!Object.hasOwn(env, varName)) continue;

        const envRegex = new RegExp(`{{${escapeRegex(varName)}}}`, 'gi');
        const envReplace = () => {
            const param = env[varName];
            const value = MacrosParser.sanitizeMacroValue(typeof param === 'function' ? param(nonce) : param);
            return value;
        };

        envMacros.push({ regex: envRegex, replace: envReplace });
    }

    const macros = [...preEnvMacros, ...envMacros, ...postEnvMacros];

    for (const macro of macros) {
        // Stop if the content is empty
        if (!content) {
            break;
        }

        // Short-circuit if no curly braces are found
        if (!macro.regex.source.startsWith('<') && !content.includes('{{')) {
            break;
        }

        try {
            content = content.replace(macro.regex, (...args) => postProcessFn(macro.replace(...args)));
        } catch (e) {
            console.warn(`Macro content can't be replaced: ${macro.regex} in ${content}`, e);
        }
    }

    return content;
}
